const std::string token="56565656565656565656565656565656";
void check(bool yes,const std::string& text){if(!yes)throw std::runtime_error(text);}
template<class F>void error(const std::string& code,F callback){try{callback();}catch(const DbError& e){check(e.code==code,"expected "+code+", got "+e.code+": "+e.what());return;}throw std::runtime_error("missing "+code);}
json sql(Engine& db,const std::string& s,const std::string& text){auto result=db.execute(s,text);check(result.value("ok",false),text+": "+result.dump());return result;}
StorageOptions opts(const fs::path& fence){StorageOptions o;o.fencing_directory=fence.u8string();return o;}
json rows(Engine& db,const std::string& s){return sql(db,s,"SELECT id,v FROM t ORDER BY id")["rows"];}
void write_marker(const fs::path& path,const json& data){std::ofstream out(path,std::ios::binary|std::ios::trunc);out<<data.dump();out.flush();check(bool(out),"test marker write failed");}
json fixture(const fs::path& root){fs::create_directories(root);auto primary=root/"primary",fence=root/"fence";Engine db(primary.u8string(),2,32u*1024u*1024u,opts(fence));auto s=db.open_session();sql(db,s,"CREATE TABLE t(id INTEGER PRIMARY KEY,v VARCHAR(100))");sql(db,s,"INSERT INTO t VALUES(1,'原始一'),(2,'原始二')");auto backup=db.backup("base");auto identity=db.recovery_identity();return {{"primary",primary.u8string()},{"fence",fence.u8string()},{"backup",backup["directory"]},{"base_end_lsn",backup["end_lsn"]},{"identity",identity}};}
json units(const fs::path& root){fs::create_directories(root);json passed=json::array();auto setup=fixture(root/"live");auto primary=fs::u8path(setup["primary"].get<std::string>()),fence=fs::u8path(setup["fence"].get<std::string>());auto options=opts(fence);auto standby_dir=root/"live/standby";
 Engine primary_db(primary.u8string(),2,32u*1024u*1024u,options);auto session=primary_db.open_session();
 sql(primary_db,session,"BEGIN");sql(primary_db,session,"INSERT INTO t VALUES(99,'未提交私有页')");error("BUSY",[&]{primary_db.backup("busy",20);});check(!fs::exists(primary/"backups/busy"),"busy backup created target data");
 auto pending=std::async(std::launch::async,[&]{return primary_db.backup("after_rollback",1000);});
 auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(2);while(!primary_db.recovery_identity().value("maintenance_requested",false)){check(std::chrono::steady_clock::now()<deadline,"backup never established maintenance barrier");std::this_thread::sleep_for(std::chrono::milliseconds(1));}
 check(pending.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready,"backup completed while private transaction active");sql(primary_db,session,"ROLLBACK");check(pending.wait_for(std::chrono::seconds(3))==std::future_status::ready,"backup did not finish after transaction rollback");auto consistent=pending.get();check(consistent["consistency"].get<std::string>().find("writes paused")!=std::string::npos,"backup overclaims no-pause hot mode");
 primary_db.set_archiving(true);sql(primary_db,session,"INSERT INTO t VALUES(3,'归档一')");auto first=primary_db.archive_wal();sql(primary_db,session,"UPDATE t SET v='归档二' WHERE id=1");auto second=primary_db.archive_wal();auto old_generation=second.at("generation").get<std::uint64_t>();primary_db.checkpoint();check(!fs::exists(primary/("wal-"+std::to_string(old_generation)+".log"))&&fs::exists(fs::u8path(second["manifest_path"].get<std::string>())),"checkpoint removed old generation before archiving");
 sql(primary_db,session,"INSERT INTO t VALUES(4,'下一代')");auto third=primary_db.archive_wal();
 auto restore=r::restore_backup(consistent["directory"],{second["manifest_path"],third["manifest_path"]},first["end_lsn"],standby_dir.u8string());
 Engine standby(standby_dir.u8string(),2,32u*1024u*1024u,options);auto replica=standby.open_session();check(rows(standby,replica)==json::array({json::array({1,"原始一"}),json::array({2,"原始二"}),json::array({3,"归档一"})}),"live backup included uncommitted/future rows");
 auto rejected=standby.execute(replica,"INSERT INTO t VALUES(90,'禁止写入')");check(!rejected.value("ok",true)&&rejected["error"]["code"]=="RECOVERY_READ_ONLY","recovered role was only a label");standby.become_standby();rejected=standby.execute(replica,"UPDATE t SET v='非法' WHERE id=1");check(!rejected.value("ok",true)&&rejected["error"]["code"]=="STANDBY_READ_ONLY","standby SQL write not blocked by private page entry");rejected=standby.execute(replica,"DELETE FROM t WHERE id=999999");check(!rejected.value("ok",true)&&rejected["error"]["code"]=="STANDBY_READ_ONLY","zero-row DML bypassed standby write intent guard");
 auto imported=standby.import_data(replica,{{"format","csv"},{"table","t"},{"header",true},{"content","id,v\n91,not_allowed\n"}});check(!imported.value("ok",true)&&rows(standby,replica).size()==3,"standby CSV bypassed kernel role");
 passed.push_back({{"case","actual_SQL_live_backup_BUSY_wait_rollback_and_exact_PITR"},{"status","PASS"},{"restore",restore}});
 auto old_timeline=primary_db.recovery_identity()["timeline"];sql(primary_db,session,"BEGIN");sql(primary_db,session,"UPDATE t SET v='提升前私有修改' WHERE id=1");auto promoted=standby.promote();check(promoted["timeline"]!=old_timeline&&promoted["fence_epoch"].get<std::uint64_t>()>1,"promotion did not change shared timeline/epoch");
 rejected=primary_db.execute(session,"COMMIT");check(!rejected.value("ok",true)&&rejected["error"]["code"]=="FENCED","old private transaction crossed promotion and got commit confirmation");sql(primary_db,session,"ROLLBACK");rejected=primary_db.execute(session,"INSERT INTO t VALUES(92,'旧主写入')");check(!rejected.value("ok",true)&&rejected["error"]["code"]=="FENCED","old primary private write accepted after promotion");check(!primary_db.recovery_identity().value("writable",true),"old primary diagnostics still writable");
 sql(standby,replica,"INSERT INTO t VALUES(5,'提升后新主')");check(rows(standby,replica).size()==4,"promoted primary not writable");sql(standby,replica,"VERIFY");passed.push_back({{"case","actual_SQL_role_CSV_commit_fencing_and_timeline_promotion"},{"status","PASS"},{"promotion",promoted}});

 auto network_setup=fixture(root/"wire");auto net_primary=fs::u8path(network_setup["primary"].get<std::string>()),net_fence=fs::u8path(network_setup["fence"].get<std::string>()),net_standby=root/"wire/standby";
 r::restore_backup(network_setup["backup"],{},network_setup["base_end_lsn"],net_standby.u8string());
 Engine source(net_primary.u8string(),2,32u*1024u*1024u,opts(net_fence)),destination(net_standby.u8string(),2,32u*1024u*1024u,opts(net_fence));auto source_session=source.open_session(),dest_session=destination.open_session();destination.become_standby();auto identity=destination.recovery_identity();r::ReceiverOptions receiver_options;receiver_options.database_uuid=identity["uuid"];receiver_options.timeline=identity["timeline"];receiver_options.inbox_directory=(net_standby/"inbox").u8string();receiver_options.owner_directory=net_standby.u8string();receiver_options.base_lsn=identity["durable_lsn"];receiver_options.token=token;
 r::StandbyReceiver receiver(receiver_options,[&](const std::string& path,bool validate){return destination.replay_archive(path,100,validate);});receiver.start();
 sql(source,source_session,"INSERT INTO t VALUES(3,'真实网络传输')");auto shipment=source.archive_wal();auto ack=r::ship_archive(shipment["manifest_path"],receiver.port(),token);check(ack["forced_lsn"]==shipment["end_lsn"]&&ack["replayed_lsn"]==shipment["end_lsn"]&&rows(destination,dest_session).size()==3,"network receive/force/replay and actual SQL diverged");auto duplicate=r::ship_archive(shipment["manifest_path"],receiver.port(),token);check(duplicate["replay"]["appended_wal_bytes"]==0&&duplicate["replay"]["data_pages_written"]==0,"duplicate physical shipment was applied twice");
 sql(destination,dest_session,"BEGIN");sql(destination,dest_session,"SELECT * FROM t");sql(source,source_session,"UPDATE t SET v='读事务后重放' WHERE id=1");auto later=source.archive_wal();error("REPLICATION_REJECTED",[&]{r::ship_archive(later["manifest_path"],receiver.port(),token);});check(receiver.status()["forced_lsn"]==shipment["end_lsn"],"BUSY unadmitted segment advanced forced watermark");sql(destination,dest_session,"ROLLBACK");auto caught_up=r::ship_archive(later["manifest_path"],receiver.port(),token);check(rows(destination,dest_session)[0][1]=="读事务后重放"&&caught_up["replayed_lsn"]==later["end_lsn"],"retry after read barrier did not replay");receiver.stop();passed.push_back({{"case","actual_loopback_receive_force_replay_duplicate_and_read_barrier"},{"status","PASS"},{"first_ack",ack},{"caught_up",caught_up}});
 return {{"status","PASS"},{"checks",passed},{"scope","Real Engine SQL through isolated replacement Storage/SQL; Windows native files and actual loopback"}};
}
void service(const std::string& role,const fs::path& directory,const fs::path& fence,const std::string& phase){
 auto options=opts(fence);bool fired=false;auto hook=[&](const char* point){if(!fired&&!phase.empty()&&phase==point){fired=true;write_marker(directory/"control-phase-ready.json",{{"phase",point}});std::this_thread::sleep_for(std::chrono::seconds(20));throw std::runtime_error("expected external process termination at controlled phase");}};options.recovery_phase_hook=hook;
 Engine db(directory.u8string(),2,32u*1024u*1024u,options);auto session=db.open_session();std::unique_ptr<r::StandbyReceiver> receiver;
 if(role=="standby"&&db.recovery_identity()["role"]!="PRIMARY"){if(db.recovery_identity()["role"]=="RESTORED_READ_ONLY")db.become_standby();auto id=db.recovery_identity();r::ReceiverOptions configuration;configuration.database_uuid=id["uuid"];configuration.timeline=id["timeline"];configuration.inbox_directory=(directory/"inbox").u8string();configuration.owner_directory=directory.u8string();configuration.base_lsn=id["durable_lsn"];configuration.token=token;configuration.phase_hook=hook;receiver=std::make_unique<r::StandbyReceiver>(configuration,[&](const std::string& path,bool validate){return db.replay_archive(path,500,validate);});receiver->start();}
 if(role=="primary-pending"){sql(db,session,"BEGIN");sql(db,session,"UPDATE t SET v='旧主尚未提交' WHERE id=1");}
 httplib::Server controller;controller.new_task_queue=[](){return new httplib::ThreadPool(2);};controller.set_payload_max_length(32768);controller.set_read_timeout(3,0);controller.set_write_timeout(3,0);std::atomic<bool> done{false};std::mutex calls;
 controller.Post("/control",[&](const httplib::Request& request,httplib::Response& response){if(request.get_header_value("X-EduDB-Token")!=token){response.status=403;return;}std::lock_guard<std::mutex> lock(calls);try{auto body=json::parse(request.body);auto action=body.at("action").get<std::string>();json out;if(action=="sql")out=db.execute(session,body.at("sql"));else if(action=="identity")out=db.recovery_identity();else if(action=="archive")out=db.archive_wal();else if(action=="backup")out=db.backup(body.value("label",std::string("snapshot")),body.value("timeout_ms",500));else if(action=="promote"){out=db.promote(500);if(receiver)receiver->stop();}else if(action=="checkpoint")out=db.checkpoint();else if(action=="stop"){done=true;out={{"ok",true}};}else throw DbError("ARGUMENT","unknown controller action");response.set_content(out.dump(),"application/json");}catch(const DbError& e){response.status=409;response.set_content(json{{"ok",false},{"error",{{"code",e.code},{"message",e.what()}}}}.dump(),"application/json");}catch(const std::exception& e){response.status=500;response.set_content(json{{"ok",false},{"error",e.what()}}.dump(),"application/json");}});
 auto port=controller.bind_to_any_port("127.0.0.1");check(port>0,"controller bind failed");std::thread thread([&]{controller.listen_after_bind();});while(!controller.is_running())std::this_thread::sleep_for(std::chrono::milliseconds(1));write_marker(directory/"control-service-ready.json",{{"controller_port",port},{"receiver_port",receiver?receiver->port():0},{"token",token},{"identity",db.recovery_identity()}});std::cout<<"READY\n"<<std::flush;
 auto end=std::chrono::steady_clock::now()+std::chrono::seconds(60);while(!done&&std::chrono::steady_clock::now()<end)std::this_thread::sleep_for(std::chrono::milliseconds(10));controller.stop();thread.join();if(receiver)receiver->stop();db.close_session(session);
}
