int main(int argc,char** argv){try{if(argc==1){auto root=fs::absolute(fs::path("backup_sql-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())));std::cout<<units(root).dump(2)<<"\n";return 0;}if(argc==3&&std::string(argv[1])=="--unit"){std::cout<<units(fs::u8path(argv[2])).dump(2)<<"\n";return 0;}if(argc==3&&std::string(argv[1])=="--fixture"){std::cout<<fixture(fs::u8path(argv[2])).dump(2)<<"\n";return 0;}if(argc==6&&std::string(argv[1])=="--service"){service(argv[2],fs::u8path(argv[3]),fs::u8path(argv[4]),argv[5]);return 0;}if(argc==4&&std::string(argv[1])=="--ship"){std::cout<<r::ship_archive(argv[2],static_cast<unsigned>(std::stoul(argv[3])),token).dump(2)<<"\n";return 0;}if(argc>=5&&std::string(argv[1])=="--restore"){std::vector<std::string> archives;for(int n=5;n<argc;++n)archives.push_back(argv[n]);std::cout<<r::restore_backup(argv[2],archives,std::stoull(argv[3]),argv[4]).dump(2)<<"\n";return 0;}throw std::runtime_error("usage --unit|--fixture ROOT; --service ROLE DIR FENCE PHASE; --ship MANIFEST PORT; --restore BACKUP TARGET NEWDIR [ARCHIVES]");}catch(const DbError& e){std::cerr<<json{{"status","ERROR"},{"code",e.code},{"message",e.what()}}.dump()<<"\n";return 4;}catch(const std::exception& e){std::cerr<<json{{"status","FAIL"},{"message",e.what()}}.dump()<<"\n";return 5;}}
